package com.atlashub.pay.txquery.application.queries.ListTransactions;

import com.atlashub.pay.txquery.application.queries.TransactionResultMapper;import com.atlashub.pay.txquery.application.queries.TransactionResults.TransactionResult;import com.atlashub.pay.txquery.domain.repositories.TransactionRecordRepository;import com.atlashub.pay.txquery.domain.valueobject.TransactionFilter;import com.atlashub.shared.application.usecase.Query;import com.atlashub.shared.domain.valueobject.PageResult;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Component;

@Component
public class ListTransactionsHandler extends Query<ListTransactionsQuery,PageResult<TransactionResult>> {private final TransactionRecordRepository repository;private final TransactionResultMapper mapper;public ListTransactionsHandler(TransactionRecordRepository r,TransactionResultMapper m){repository=r;mapper=m;}@Override @PreAuthorize("hasAuthority('pay:ledger:read')") public PageResult<TransactionResult> execute(ListTransactionsQuery q){var result=repository.search(new TransactionFilter(q.organizationId(),q.environment(),q.accountId(),q.type(),q.status(),q.direction(),q.channel(),q.provider(),q.sourceSystem(),q.sourceReferenceId(),q.partyType(),q.partyReferenceId(),q.outletId(),q.currency(),q.reference(),q.search(),q.minAmount(),q.maxAmount(),q.from(),q.to(),q.page(),q.size(),q.sortDirection()));return new PageResult<>(result.content().stream().map(record -> mapper.map(record, q.accountId())).toList(),result.pageNumber(),result.pageSize(),result.totalElements(),result.totalPages());}}
